<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
  <style>
    :root {
      --bg-color: #1a1a1f;
      --panel-bg: linear-gradient(135deg, #2a2833 0%, #353340 100%);
      --accent-purple: #8b7d9b;
      --accent-silver: #c4c4cc;
      --text-main: #e0e0e0;
      --text-sub: #a09da8;
      --item-bg: rgba(196, 196, 204, 0.05);
      --border-color: rgba(139, 125, 155, 0.3);
      --border-silver: rgba(196, 196, 204, 0.2);
    }

    body {
      margin: 0;
      padding: 0;
      background-color: var(--bg-color);
      color: var(--text-main);
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      font-size: 13px;
      line-height: 1.4;
    }

    .container {
      padding: 4px;
      display: flex;
      flex-direction: column;
      gap: 6px;
    }

    .section {
      background: var(--panel-bg);
      border: 1px solid var(--border-color);
      border-radius: 6px;
      padding: 6px;
      box-shadow: 0 2px 8px rgba(0,0,0,0.2);
    }

    .section-title {
      font-size: 12px;
      color: var(--accent-silver);
      border-bottom: 1px solid var(--border-silver);
      padding-bottom: 3px;
      margin-bottom: 4px;
      text-transform: uppercase;
      letter-spacing: 1px;
      font-weight: bold;
    }

    .kv-list {
      display: flex;
      flex-direction: column;
      gap: 3px;
    }

    .kv-row {
      display: flex;
      justify-content: space-between;
      align-items: center;
      background: var(--item-bg);
      padding: 3px 6px;
      border-radius: 4px;
      border: 1px solid rgba(255,255,255,0.02);
    }

    .kv-key {
      color: var(--accent-purple);
      font-size: 12px;
      white-space: nowrap;
    }

    .kv-val {
      color: var(--text-main);
      text-align: right;
      font-weight: 500;
      word-break: break-all;
    }


    .char-card {
      background: rgba(0,0,0,0.15);
      border: 1px solid var(--border-color);
      border-radius: 6px;
      margin-bottom: 6px;
      overflow: hidden;
      position: relative; 
      padding-top: 10px; 
    }

    .char-avatar {
      position: absolute;
      top: 8px;
      left: 6px;
      width: 48px; 
      height: 48px;
      border-radius: 4px;
      background: rgba(255,255,255,0.05);
      border: 1px solid var(--accent-purple);
      padding: 2px;
      z-index: 2;
    }

    .char-name {
      position: absolute;
      top: 8px;
      left: 62px; 
      font-size: 16px;
      font-weight: bold;
      color: var(--accent-silver);
      text-shadow: 0 0 4px rgba(196,196,204,0.3);
    }

    .char-content-wrapper {
        padding-top: 30px; 
    }

    .char-basic {
      padding: 4px 4px 4px 10px; 
      display: flex;
      flex-direction: column;
      gap: 3px;
    }


    .char-basic .kv-row:nth-child(1),
    .char-basic .kv-row:nth-child(2) {
        margin-left: 42px; 
    }


    .collapsible {
      margin: 2px 4px 4px 4px;
      border: 1px solid var(--border-silver);
      border-radius: 4px;
      overflow: hidden;
    }

    .collapsible-header {
      background: rgba(139,125,155,0.1);
      padding: 4px 6px;
      font-size: 12px;
      color: var(--accent-purple);
      display: flex;
      justify-content: space-between;
      align-items: center;
    }

    .collapsible-header::after {
      content: '▼';
      font-size: 10px;
      transition: transform 0.2s;
    }

    .collapsible.active .collapsible-header::after {
      transform: rotate(180deg);
    }

    .collapsible-content {
      display: none;
      padding: 4px;
      background: rgba(0,0,0,0.2);
      border-top: 1px solid var(--border-silver);
    }

    .collapsible.active .collapsible-content {
      display: block;
    }


    .text-block {
      background: var(--item-bg);
      padding: 4px;
      border-radius: 4px;
      margin-bottom: 3px;
      font-size: 12px;
      color: #ccc;
    }
    .text-block-title {
      color: var(--accent-silver);
      font-weight: bold;
      margin-bottom: 2px;
    }


    .pagination {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding: 4px 0;
    }
    .btn {
      background: var(--accent-purple);
      color: #fff;
      border: none;
      padding: 4px 12px;
      border-radius: 4px;
      font-size: 12px;
    }
    .btn:disabled {
      background: #444;
      color: #888;
    }
    .page-info {
      color: var(--accent-silver);
      font-size: 12px;
    }
  </style>
  <script src="https://code.jquery.com/jquery-3.6.0.min.js"></script>
