ke-linejoin:miter;stroke-dasharray:none;stroke-opacity:1" d="M 6.7638484,10.962099 5.7142857,13.387755" /></g><g><path style="fill:#666666;fill-opacity:1;stroke:#666666;stroke-width:0.636;stroke-linejoin:miter;stroke-dasharray:none;stroke-opacity:1" d="M 5.9941691,9.7725947 6.2040817,12.804665 8.7696793,12.478135 8.5364432,10.075802 Z" /><path style="fill:#cccccc;fill-opacity:1;stroke:#cccccc;stroke-opacity:1" d="M 5.7842566,9.2594752 8.3498542,11.008746 11.125364,9.0029155 11.988338,6.5306122 11.311953,3.2419825 6.9037901,2.728863 3.8483965,5.7376093 4.6880466,8.6997085 Z" /><path style="fill:#808080;fill-opacity:1;stroke:#808080;stroke-opacity:1" d="M 8.8629738,4.244898 9.6559767,6.2040816 9.0029155,7.6734694 11.03207,5.6209913 9.819242,1.7259475 Z" /><path style="fill:#808080;fill-opacity:1;stroke:#808080;stroke-opacity:1" d="M 9.6326531,0.60641399 5.3411079,1.0728863 2.2623907,6.0408163 3.7784257,10.542274 6.2507289,11.218659 5.2944606,6.483965 8.4198251,4.7346939 Z" /><path style="fill:#808080;fill-opacity:1;stroke:#808080;stroke-opacity:1" d="m 12.034985,5.5976676 c 0.233237,0.3265307 1.212828,3.2653062 1.212828,3.2653062 L 12.244898,11.428571 14.204082,7.4169096 13.341108,2.8221574 10.285714,1.7259475 Z" /><path style="fill:#808080;fill-opacity:1;stroke:#808080;stroke-width:0.636;stroke-linejoin:bevel;stroke-dasharray:none;stroke-opacity:1" d="M 2.9353593,5.6577381 0.72289507,11.104424 3.6985974,8.1248817 Z" /><path style="fill:#808080;fill-opacity:1;stroke:#808080;stroke-width:0.636;stroke-linejoin:bevel;stroke-dasharray:none;stroke-opacity:1" d="M 4.7966205,2.4664344 2.1772509,4.1218331 4.4621528,3.3288898 Z" /><path style="fill:#cccccc;fill-opacity:1;stroke:#cccccc;stroke-width:0.636;stroke-linejoin:miter;stroke-dasharray:none;stroke-opacity:1" d="m 3.2653061,13.177843 -2.0991253,0.653061 2.0291545,2.309038 8.6997087,0.209912 1.142857,-2.075802 -2.845481,-0.932944" /><path style="fill:#cccccc;fill-opacity:1;stroke:#cccccc;stroke-width:0.636;stroke-linejoin:miter;stroke-dasharray:none;stroke-opacity:1" d="M 3.0787172,12.991254 10.19242,13.107872" /><path style="fill:#cccccc;fill-opacity:1;stroke:#cccccc;stroke-width:0.636;stroke-linejoin:miter;stroke-dasharray:none;stroke-opacity:1" d="M 13.107872,14.880466 12.89796,17.212828 10.915452,17.072886 Z" /><path style="fill:#999999;fill-opacity:1;stroke:#999999;stroke-width:0.636;stroke-linejoin:miter;stroke-dasharray:none;stroke-opacity:1" d="m 0.67638484,13.784257 4.08163266,3.195335 -1.8425656,0.02332 z" /><path style="fill:#999999;fill-opacity:1;stroke:#999999;stroke-width:0.636;stroke-linejoin:miter;stroke-dasharray:none;stroke-opacity:1" d="m 13.411079,14.250729 -0.209913,3.03207 -0.209912,-0.233236 z" /><path style="fill:#999999;fill-opacity:1;stroke:#999999;stroke-width:0.636;stroke-linejoin:miter;stroke-dasharray:none;stroke-opacity:1" d="m 8.7696794,14.857143 c 0.1865889,0.326531 1.9125356,3.381924 1.9125356,3.381924 L 8.4198251,18.052478 Z" /><path style="fill:#666666;fill-opacity:1;stroke:#666666;stroke-width:0.636;stroke-linejoin:miter;stroke-dasharray:none;stroke-opacity:1" d="M 9.516035,3.2186589 8.6530612,5.4344023 9.3294461,6.2507289 Z" /></g><g><path style="fill:#e6e6e6;fill-opacity:1;stroke:#e6e6e6;stroke-width:0.636;stroke-linejoin:miter;stroke-dasharray:none;stroke-opacity:1" d="M 8.0932944,13.061225 7.9533527,14.647231 3.2419825,12.711371 4.6880466,11.661808 Z" /><path style="fill:#e6e6e6;fill-opacity:1;stroke:#e6e6e6;stroke-width:0.575442;stroke-linejoin:miter;stroke-dasharray:none;stroke-opacity:1" d="m 8.721012,12.868001 0.6935746,1.39652 0.5271168,-0.850754 -0.3329158,-1.316259 z" /></g></g></svg>`;

    let currentPage = 1;
    const itemsPerPage = 3;
    let charactersList = [];

    function renderRow(key, val) {
      return `<div class="kv-row"><span class="kv-key">${key}</span><span class="kv-val">${val}</span></div>`;
    }

    function renderObjToText(obj) {
      if (!obj || typeof obj !== 'object') return '';
      return Object.entries(obj).map(([k, v]) => `<div class="text-block"><div class="text-block-title">${k}</div>${v}</div>`).join('');
    }

    function populateCharacterData() {
      const all_variables = getAllVariables();

      $('#loc-time').text(_.get(all_variables, 'stat_data.文本1.文本2', 'N/A'));
      $('#loc-region').text(_.get(all_variables, 'stat_data.文本1.文本3.文本4', 'N/A'));
      $('#loc-city').text(_.get(all_variables, 'stat_data.文本1.文本3.文本5', 'N/A'));
      $('#loc-facility').text(_.get(all_variables, 'stat_data.文本1.文本3.文本6', 'N/A'));

      $('#auth-name').text(_.get(all_variables, 'stat_data.文本7.文本8', 'N/A'));
      $('#auth-age').text(_.get(all_variables, 'stat_data.文本7.文本9', 'N/A'));
      $('#auth-sex-count').text(_.get(all_variables, 'stat_data.文本7.文本10', 0));
      $('#auth-first-count').text(_.get(all_variables, 'stat_data.文本7.文本11', 0));
      $('#auth-preg-count').text(_.get(all_variables, 'stat_data.文本7.文本12', 0));
      $('#auth-money').text(_.get(all_variables, 'stat_data.文本7.文本13', 0) + ' 文本14');

      const charsObj = _.get(all_variables, 'stat_data.文本15', {});
      charactersList = Object.entries(charsObj);

      renderCharacterPage();
    }

    function renderCharacterPage() {
      const container = $('#characters-container');
      container.empty();

      if (charactersList.length === 0) {
        container.html('<div style="text-align:center; padding:10px; color:#888;">文本16</div>');
        $('#page-info').text('0 / 0');
        $('#btn-prev').prop('disabled', true);
        $('#btn-next').prop('disabled', true);
        return;
      }

      const totalPages = Math.ceil(charactersList.length / itemsPerPage);
      if (currentPage > totalPages) currentPage = totalPages;
      if (currentPage < 1) currentPage = 1;

      $('#page-info').text(`${currentPage} / ${totalPages}`);
      $('#btn-prev').prop('disabled', currentPage === 1);
      $('#btn-next').prop('disabled', currentPage === totalPages);

      const start = (currentPage - 1) * itemsPerPage;
      const end = start + itemsPerPage;
      const pageItems = charactersList.slice(start, end);

      pageItems.forEach(([name, data]) => {
        const basicHTML = `
          ${renderRow('文本17/文本18', `${data.文本17 || '?'} / ${data.文本18 || '?'}`)}
          ${renderRow('文本19/文本20', `${data.文本21 || '?'} / ${data.文本20 || '?'}`)}
          ${renderRow('文本22', `${data.文本23 || '?'}`)}
          ${renderRow('文本24', `${data.文本25 || '文本26'}`)}
        `;

        const detailHTML = `
          <div class="kv-list">
            ${renderRow('文本27', data.文本28 || '?')}
            ${renderRow('文本29', (data.文本30||'') + ' ' + (data.文本29||''))}
            ${renderRow('文本31', data.文本31 || '?')}
            ${renderRow('文本32', data.文本32 || '?')}
            ${renderRow('文本33', (data.文本34||'') + ' ' + (data.文本33||''))}
            ${renderRow('文本35', data.文本35 || '?')}
            ${renderRow('文本36', data.文本36 || '?')}
            ${renderRow('文本37', data.文本37 || '?')}
          </div>
        `;

        let sexExpStr = renderObjToText(data.文本43);
        if(!sexExpStr) sexExpStr = '<div class="text-block">文本38</div>';

        let pregStr = renderObjToText(data.文本40?.文本54);
        pregStr += `<div class="text-block"><div class="text-block-title">文本39</div>${data.文本40?.文本39 || '文本26'}</div>`;

        const nsfwHTML = `
          <div class="kv-list">
            <div class="text-block"><div class="text-block-title">文本41</div>${data.文本41 || '文本42'}</div>
            <div class="text-block-title" style="margin-top:4px;">文本43</div>
            ${sexExpStr}
            <div class="text-block-title" style="margin-top:4px;">文本44</div>
            ${pregStr}
          </div>
        `;

        const modStr = renderObjToText(data.文本52);
        const modHTML = `<div class="kv-list">${modStr || '<div class="text-block">文本45</div>'}</div>`;

        let expHTML = '';
        if(data.文本47) {
          expHTML += `<div class="text-block-title">文本46</div>${renderObjToText(data.文本47.文本46)}`;
          expHTML += `<div class="text-block-title">文本48</div>${renderObjToText(data.文本47.文本48)}`;
          expHTML += `<div class="text-block-title">文本49</div>${renderObjToText(data.文本47.文本49)}`;
        } else {
          expHTML = '<div class="text-block">文本38</div>';
        }

        const card = `
          <div class="char-card">
            <div class="char-avatar">${avatarSVG}</div>
            <div class="char-name">${name}</div>
            <div class="char-content-wrapper">
                <div class="char-basic">
                  ${basicHTML}
                </div>

                <div class="collapsible">
                  <div class="collapsible-header">文本50</div>
                  <div class="collapsible-content">${detailHTML}</div>
                </div>

                <div class="collapsible">
                  <div class="collapsible-header">文本51</div>
                  <div class="collapsible-content">${nsfwHTML}</div>
                </div>

                <div class="collapsible">
                  <div class="collapsible-header">文本52</div>
                  <div class="collapsible-content">${modHTML}</div>
                </div>

                <div class="collapsible">
                  <div class="collapsible-header">文本53</div>
                  <div class="collapsible-content">${expHTML}</div>
                </div>
            </div>
          </div>
        `;
        container.append(card);
      });

      $('.collapsible-header').off('click').on('click', function() {
        $(this).parent().toggleClass('active');
      });
    }

    async function init() {
      await waitGlobalInitialized('Mvu');

      $('#btn-prev').on('click', () => {
        if(currentPage > 1) { currentPage--; renderCharacterPage(); }
      });
      $('#btn-next').on('click', () => {
        const total = Math.ceil(charactersList.length / itemsPerPage);
        if(currentPage < total) { currentPage++; renderCharacterPage(); }
      });

      populateCharacterData();

      eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, () => {
        populateCharacterData();
      });
    }

    $(errorCatched(init));
  </script>
</head>
<body>
  <div class="container">

    <div class="section">
      <div class="section-title">文本55 | 文本1</div>
      <div class="kv-list">
        <div class="kv-row"><span class="kv-key">文本2</span><span class="kv-val" id="loc-time">-</span></div>
        <div class="kv-row"><span class="kv-key">文本4</span><span class="kv-val" id="loc-region">-</span></div>
        <div class="kv-row"><span class="kv-key">文本5</span><span class="kv-val" id="loc-city">-</span></div>
        <div class="kv-row"><span class="kv-key">文本6</span><span class="kv-val" id="loc-facility">-</span></div>
      </div>
    </div>

    <div class="section">
      <div class="section-title">文本56 | 文本7</div>
      <div class="kv-list">
        <div class="kv-row"><span class="kv-key">文本57</span><span class="kv-val" id="auth-name">-</span></div>
        <div class="kv-row"><span class="kv-key">文本17</span><span class="kv-val" id="auth-age">-</span></div>
        <div class="kv-row"><span class="kv-key">文本10</span><span class="kv-val" id="auth-sex-count">-</span></div>
        <div class="kv-row"><span class="kv-key">文本58</span><span class="kv-val" id="auth-first-count">-</span></div>
        <div class="kv-row"><span class="kv-key">文本59</span><span class="kv-val" id="auth-preg-count">-</span></div>
        <div class="kv-row"><span class="kv-key">文本60</span><span class="kv-val" id="auth-money">-</span></div>
      </div>
    </div>

    <div class="section">
      <div class="section-title" style="display:flex; justify-content:space-between; align-items:center;">
        <span>文本61 | 文本62</span>
      </div>

      <div id="characters-container">
        </div>

      <div class="pagination">
        <button class="btn" id="btn-prev">文本63</button>
        <span class="page-info" id="page-info">1 / 1</span>
        <button class="btn" id="btn-next">文本64</button>
      </div>
    </div>

  </div>
