      gap: 3px;
    }

    .kv-row {
      display: flex;
      justify-content: space-between;
      align-items: center;
      background: var(--item-bg);
      padding: 3px 6px;
      border-radius: 4px;
      border: 1px solid rgba(255,255,255,0.02);
    }

    .kv-key {
      color: var(--accent-purple);
      font-size: 11px;
      white-space: nowrap;
    }

    .kv-val {
      color: var(--text-main);
      text-align: right;
      font-weight: 500;
      word-break: break-all;
      font-size: 12px;
    }


    .char-card {
      background: rgba(0,0,0,0.15);
      border: 1px solid var(--border-color);
      border-radius: 6px;
      margin-bottom: 6px;
      overflow: hidden;
      padding: 6px;
    }

    .char-top-layout {
      display: flex;
      gap: 8px;
      align-items: flex-start;
      margin-bottom: 6px;
    }


    .char-profile {
      display: flex;
      flex-direction: column;
      align-items: center;
      width: 60px;
      flex-shrink: 0;
    }

    .char-avatar {
      width: 56px;
      height: 56px;
      border-radius: 4px;
      background: rgba(255,255,255,0.05);
      border: 1px solid var(--accent-purple);
      padding: 1px;
      display: block;
    }

    .char-name {
      margin-top: 4px;
      font-size: 14px;
      font-weight: bold;
      color: var(--accent-silver);
      text-align: center;
      width: 100%;
      word-break: break-all;
      line-height: 1.2;
      text-shadow: 0 0 4px rgba(196,196,204,0.3);
    }


    .char-info-summary {
      flex-grow: 1;
      display: flex;
      flex-direction: column;
      gap: 3px;
    }

    .collapsible {
      margin: 2px 0px 4px 0px;
      border: 1px solid var(--border-silver);
      border-radius: 4px;
      overflow: hidden;
    }

    .collapsible-header {
      background: rgba(139,125,155,0.1);
      padding: 4px 6px;
      font-size: 12px;
      color: var(--accent-purple);
      display: flex;
      justify-content: space-between;
      align-items: center;
    }

    .collapsible-header::after {
      content: '▼';
      font-size: 10px;
      transition: transform 0.2s;
    }

    .collapsible.active .collapsible-header::after {
      transform: rotate(180deg);
    }

    .collapsible-content {
      display: none;
      padding: 4px;
      background: rgba(0,0,0,0.2);
      border-top: 1px solid var(--border-silver);
    }

    .collapsible.active .collapsible-content {
      display: block;
    }

    .text-block {
      background: var(--item-bg);
      padding: 4px;
      border-radius: 4px;
      margin-bottom: 3px;
      font-size: 12px;
      color: #ccc;
    }
    .text-block-title {
      color: var(--accent-silver);
      font-weight: bold;
      margin-bottom: 2px;
    }

    .pagination {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding: 4px 0;
    }
    .btn {
      background: var(--accent-purple);
      color: #fff;
      border: none;
      padding: 4px 12px;
      border-radius: 4px;
      font-size: 12px;
    }
    .btn:disabled {
      background: #444;
      color: #888;
    }
    .page-info {
      color: var(--accent-silver);
      font-size: 12px;
