    .char-identity {
      margin-top: 2px;
      font-size: 11px;
      color: var(--text-sub); 
      text-align: center;
      width: 100%;
      line-height: 1.2;
    }


    .char-info-summary {
      flex-grow: 1;
      display: flex;
      flex-direction: column;
      gap: 3px;
    }


    .collapsible-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 4px;
      margin-bottom: 4px;
    }

    .collapsible {
      border: 1px solid var(--border-silver);
      border-radius: 4px;
      overflow: hidden;
      display: flex;
      flex-direction: column;
    }

    .collapsible-header {
      background: rgba(139,125,155,0.1);
      padding: 4px;
      font-size: 11px; 
      color: var(--accent-purple);
      display: flex;
      justify-content: center; 
      align-items: center;
      gap: 4px;
      cursor: pointer;
    }

    .collapsible-header::after {
      content: '▼';
      font-size: 9px;
      transition: transform 0.2s;
    }

    .collapsible.active .collapsible-header::after {
      transform: rotate(180deg);
    }

    .collapsible-content {
      display: none;
      padding: 4px;
      background: rgba(0,0,0,0.2);
      border-top: 1px solid var(--border-silver);

    }


    .collapsible-body {
        display: none;
        padding: 4px;
        background: rgba(0,0,0,0.2);
        border: 1px solid var(--border-silver);
        border-radius: 4px;
        margin-top: -2px;
        margin-bottom: 4px;
    }

    .collapsible-body.active {
        display: block;
    }

    .text-block {
      background: var(--item-bg);
      padding: 4px;
      border-radius: 4px;
      margin-bottom: 3px;
      font-size: 12px;
      color: #ccc;
    }
    .text-block-title {
      color: var(--accent-silver);
      font-weight: bold;
      margin-bottom: 2px;
    }

    .pagination {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding: 4px 0;
    }
    .btn {
      background: var(--accent-purple);
      color: #fff;
      border: none;
      padding: 4px 12px;
      border-radius: 4px;
      font-size: 12px;
    }
    .btn:disabled {
      background: #444;
      color: #888;
    }
    .page-info {
      color: var(--accent-silver);
      font-size: 12px;
    }
